<?php
require_once __DIR__.'/../../includes/functions.php';require_admin();$error='';$notice='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=(string)($_POST['action']??'');$id=filter_var($_POST['id']??null,FILTER_VALIDATE_INT);if($action==='delete'&&$id){db()->prepare('DELETE FROM services WHERE id=?')->execute([$id]);$notice='Service deleted.';}elseif(in_array($action,['create','update'],true)){$name=trim((string)($_POST['name']??''));$description=trim((string)($_POST['description']??''));$duration=trim((string)($_POST['duration']??''));$price=trim((string)($_POST['starting_price']??''));$price=$price===''?null:filter_var($price,FILTER_VALIDATE_FLOAT);$category=filter_var($_POST['category_id']??null,FILTER_VALIDATE_INT)?:null;if($name===''||$description===''||($price!==null&&($price===false||$price<0)))$error='Enter a service name, description and a valid price.';else{try{$image=save_uploaded_image('image','services');$slug=strtolower(trim(preg_replace('/[^a-z0-9]+/','-',iconv('UTF-8','ASCII//TRANSLIT',$name)),'-')).'-'.strtolower(bin2hex(random_bytes(3)));if($action==='create')db()->prepare('INSERT INTO services (category_id,name,slug,description,starting_price,duration,image) VALUES (?,?,?,?,?,?,?)')->execute([$category,$name,$slug,$description,$price,$duration?:null,$image]);elseif($image)db()->prepare('UPDATE services SET category_id=?,name=?,description=?,starting_price=?,duration=?,image=? WHERE id=?')->execute([$category,$name,$description,$price,$duration?:null,$image,$id]);else db()->prepare('UPDATE services SET category_id=?,name=?,description=?,starting_price=?,duration=? WHERE id=?')->execute([$category,$name,$description,$price,$duration?:null,$id]);$notice='Service saved.';}catch(RuntimeException|PDOException $exception){$error=$exception instanceof RuntimeException?$exception->getMessage():'Service could not be saved.';error_log('Service save failed: '.$exception->getMessage());}}}}
$editId=filter_input(INPUT_GET,'edit',FILTER_VALIDATE_INT);$edit=null;if($editId){$q=db()->prepare('SELECT * FROM services WHERE id=?');$q->execute([$editId]);$edit=$q->fetch()?:null;}
$categories=db()->query('SELECT id,name FROM service_categories ORDER BY name')->fetchAll();$services=db()->query('SELECT s.*,sc.name AS category_name FROM services s LEFT JOIN service_categories sc ON sc.id=s.category_id ORDER BY s.name')->fetchAll();$adminTitle='Services · Yucca Fabrics';require __DIR__.'/../../includes/admin-header.php';
?>
<h1 class="font-serif text-4xl">Services</h1><?php if($error||$notice): ?><p class="mt-4 rounded p-3 text-sm <?= $error?'bg-red-50 text-red-800':'bg-green-50 text-green-800' ?>"><?= e($error?:$notice) ?></p><?php endif; ?><section class="mt-7 bg-white p-5"><h2 class="font-serif text-2xl"><?= $edit?'Edit service':'Add a service' ?></h2><form method="post" enctype="multipart/form-data" class="mt-4 grid gap-3 sm:grid-cols-2"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="<?= $edit?'update':'create' ?>"><?php if($edit): ?><input type="hidden" name="id" value="<?= (int)$edit['id'] ?>"><?php endif; ?><label class="text-sm">Name<input class="form-control mt-1" name="name" required value="<?= e($edit['name']??'') ?>"></label><label class="text-sm">Category<select class="form-control mt-1" name="category_id"><option value="">Uncategorised</option><?php foreach($categories as $cat): ?><option value="<?= (int)$cat['id'] ?>" <?= (int)($edit['category_id']??0)===(int)$cat['id']?'selected':'' ?>><?= e($cat['name']) ?></option><?php endforeach; ?></select></label><label class="text-sm">Starting price<input class="form-control mt-1" type="number" step=".01" min="0" name="starting_price" value="<?= e($edit['starting_price']??'') ?>"></label><label class="text-sm">Estimated duration<input class="form-control mt-1" name="duration" value="<?= e($edit['duration']??'') ?>"></label><label class="text-sm sm:col-span-2">Description<textarea class="form-control mt-1" name="description" required rows="3"><?= e($edit['description']??'') ?></textarea></label><label class="text-sm sm:col-span-2">Image<input class="form-control mt-1" type="file" name="image" accept="image/jpeg,image/png,image/webp"></label><div class="flex gap-4 sm:col-span-2"><button class="w-fit rounded-full bg-forest px-5 py-2 text-sm text-white"><?= $edit?'Save service':'Add service' ?></button><?php if($edit): ?><a href="<?= e(url('admin/services/index.php')) ?>" class="self-center text-sm underline">Cancel</a><?php endif; ?></div></form></section><div class="mt-6 grid gap-4 md:grid-cols-2"><?php foreach($services as $service): ?><article class="bg-white p-5"><div class="flex justify-between gap-4"><div><p class="text-xs uppercase tracking-widest text-sage"><?= e($service['category_name']??'Service') ?></p><h2 class="mt-2 font-serif text-2xl"><?= e($service['name']) ?></h2></div><div class="flex gap-3"><a class="text-sm underline" href="?edit=<?= (int)$service['id'] ?>">Edit</a><form method="post" data-confirm="Delete this service?"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?= (int)$service['id'] ?>"><button class="text-sm text-red-700 underline">Delete</button></form></div></div><p class="mt-3 text-sm leading-6 text-gray-600"><?= e($service['description']) ?></p><p class="mt-3 text-xs"><?= $service['starting_price']!==null?e(money($service['starting_price'])):'Quotation' ?> · <?= e($service['duration']??'Duration varies') ?></p></article><?php endforeach; ?></div>
<?php require __DIR__.'/../../includes/admin-footer.php'; ?>
